<?php
declare(strict_types=1);
/** Network distribution books and independent POS retail books. */
final class WalletCommerceService {
 public function __construct(private PDO $db,private AuthorizationContext $auth){}
 private function cents(mixed $s):int{if((!is_string($s)&&!is_int($s))||!preg_match('/^(\d{1,10})(?:\.(\d{1,2}))?$/',(string)$s,$m))throw new InvalidArgumentException('INVALID_AMOUNT');return (int)$m[1]*100+(int)str_pad($m[2]??'',2,'0');}
 private function money(int $n):string{return ($n<0?'-':'').intdiv(abs($n),100).'.'.str_pad((string)(abs($n)%100),2,'0',STR_PAD_LEFT);}
 private function signed(string $s):int{return str_starts_with($s,'-')?-$this->cents(substr($s,1)):$this->cents($s);}
 private function party(int $net,int $pos,int $delta,string $ref,string $type,int $cash):void{$this->db->prepare('INSERT IGNORE INTO um_admin_network_balances(network_id,admin_id,balance) VALUES(?,?,0)')->execute([$net,$pos]);$q=$this->db->prepare('SELECT balance FROM um_admin_network_balances WHERE network_id=? AND admin_id=? FOR UPDATE');$q->execute([$net,$pos]);$next=$this->signed((string)$q->fetchColumn())+$delta;$this->db->prepare('UPDATE um_admin_network_balances SET balance=? WHERE network_id=? AND admin_id=?')->execute([$this->money($next),$net,$pos]);$this->db->prepare('INSERT INTO um_financial_transactions(network_id,tx_no,account_id,tx_type,debit,credit,balance_after,cashbox_impact,payment_method,reference_id,description,created_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)')->execute([$net,'WTX-'.bin2hex(random_bytes(16)),$pos,$type,$delta>0?$this->money($delta):'0.00',$delta<0?$this->money(-$delta):'0.00',$this->money($next),$this->money($cash),$cash?'cash':'balance',$ref,'محاسبة توزيع الشبكة؛ لا يشمل قبض العميل النهائي',$this->auth->id()]);}
 public function canReverseInvoice(array $v):bool{$q=$this->db->prepare('SELECT network_invoice_id FROM um_wallet_sales WHERE network_id=? AND voucher_id=?');$q->execute([$this->auth->activeNetworkId(),$v['id']]);$id=$q->fetchColumn();return $id!==false&&(int)$id===(int)$v['invoice_id'];}
 public function payCustomerRefund(mixed $id,array $input):array{$id=$this->id($id);$net=$this->net($input);if(($input['customer_refund_paid']??false)!==true)throw new InvalidArgumentException('CUSTOMER_REFUND_CONFIRMATION_REQUIRED');$amount=$this->cents($input['amount']??'');$this->db->beginTransaction();try{$q=$this->db->prepare('SELECT * FROM um_wallet_sales WHERE network_id=? AND id=? FOR UPDATE');$q->execute([$net,$id]);$sale=$q->fetch(PDO::FETCH_ASSOC);if(!$sale)throw new DomainException('FORBIDDEN_NETWORK');$this->auth->assertCanAccessAdmin((int)$sale['pos_admin_id']);if($amount!==$this->cents($sale['retail_amount'])||$sale['status']!=='refunded')throw new DomainException('CUSTOMER_REFUND_NOT_DUE');if($sale['customer_refund_paid_at']){$this->db->commit();return ['success'=>true,'replayed'=>true];}if($amount<=0||$this->cents($sale['customer_refund_due'])!==$amount)throw new DomainException('CUSTOMER_REFUND_NOT_DUE');$this->posJournal($net,(int)$sale['pos_admin_id'],'PCR-'.$sale['invoice_no'],'customer_cash_refund',[['POS_CUSTOMER_REFUND_DUE',$amount,0],['POS_CASH',0,$amount]]);$this->db->prepare('UPDATE um_wallet_sales SET customer_refund_due=0,customer_refund_paid_at=NOW() WHERE id=? AND network_id=?')->execute([$id,$net]);$this->db->commit();return ['success'=>true,'amount'=>$this->money($amount),'book'=>'pos_only'];}catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw $e;}}
 private function id(mixed $v):int{if((!is_int($v)&&!is_string($v))||!preg_match('/^[1-9][0-9]{0,9}$/',(string)$v))throw new InvalidArgumentException('INVALID_ID');return (int)$v;}
 private function net(array $in=[]):int{if(isset($in['network_id']))$this->id($in['network_id']);$this->auth->assertCan(['wallet_sales','distributor_wallets']);$n=$this->auth->activeNetworkId();if($n<=0||!$this->auth->canAccessNetwork($n)||isset($in['network_id'])&&(int)$in['network_id']!==$n)throw new DomainException('FORBIDDEN_NETWORK');return $n;}
 private function key(array $in):string{$k=$in['request_key']??'';if(!is_string($k)||!preg_match('/^[A-Za-z0-9_.:-]{8,100}$/',$k))throw new InvalidArgumentException('REQUEST_KEY_REQUIRED');return $k;}
 private function account(int $net,string $code,string $type,string $name):int{$q=$this->db->prepare('INSERT INTO um_chart_of_accounts(network_id,account_code,name_ar,account_type,is_system,is_active) VALUES(?,?,?,?,1,1) ON DUPLICATE KEY UPDATE id=LAST_INSERT_ID(id)');$q->execute([$net,$code,$name,$type]);$q=$this->db->prepare('SELECT id FROM um_chart_of_accounts WHERE network_id=? AND account_code=? AND account_type=? AND is_active=1 FOR UPDATE');$q->execute([$net,$code,$type]);$id=(int)$q->fetchColumn();if(!$id)throw new DomainException('CHART_ACCOUNT_INVALID');return $id;}
 private function journal(string $ref,array $lines):int{require_once __DIR__.'/FinancialAccountingService.php';return (int)(new FinancialAccountingService($this->db))->createJournalEntry(['source_module'=>'wallet_distribution','reference_no'=>$ref,'description'=>'محاسبة الشبكة — '.$ref,'lines'=>$lines],$this->auth->id())['entry_id'];}
 private function posJournal(int $net,int $pos,string $ref,string $kind,array $lines):int{$d=0;$c=0;foreach($lines as $l){$d+=$l[1];$c+=$l[2];}if($d<=0||$d!==$c)throw new DomainException('POS_JOURNAL_INVALID');$q=$this->db->prepare('INSERT INTO um_pos_journals(network_id,pos_admin_id,reference_no,event_type,total_debit,total_credit,created_by) VALUES(?,?,?,?,?,?,?)');$q->execute([$net,$pos,$ref,$kind,$this->money($d),$this->money($c),$this->auth->id()]);$id=(int)$this->db->lastInsertId();$q=$this->db->prepare('INSERT INTO um_pos_journal_lines(network_id,pos_admin_id,journal_id,account_code,debit,credit) VALUES(?,?,?,?,?,?)');foreach($lines as $l)$q->execute([$net,$pos,$id,$l[0],$this->money($l[1]),$this->money($l[2])]);return $id;}
 private function profile(int $net,string $name,bool $lock=false):array{$q=$this->db->prepare('SELECT id,name,cost_price,retail_price,price,validity FROM um_profiles_def WHERE network_id=? AND name=?'.($lock?' FOR UPDATE':''));$q->execute([$net,$name]);$p=$q->fetch(PDO::FETCH_ASSOC);if(!$p)throw new DomainException('FORBIDDEN_PROFILE');$p['distribution']=$this->cents($p['cost_price']);$p['retail']=$this->cents($p['retail_price']);if($p['distribution']<=0||$p['retail']<=0)throw new DomainException('PRICES_REQUIRED');return $p;}
 private function discount(array $p,array $input):array{$d=$this->cents($input['discount_amount']??'0');$q=$this->db->prepare('SELECT discount_rate FROM um_admins WHERE id=?');$q->execute([$this->auth->id()]);$rate=in_array($this->auth->role(),['system_owner','superadmin'],true)?'100.00':(string)($q->fetchColumn()?:'0');$q=$this->db->prepare('SELECT ROUND(CAST(? AS DECIMAL(14,2))*LEAST(GREATEST(CAST(? AS DECIMAL(5,2)),0),100)/100,2)');$q->execute([$this->money($p['distribution']),$rate]);$maximum=$this->cents((string)$q->fetchColumn());if($d>$maximum||$d>=$p['distribution'])throw new DomainException('DISCOUNT_NOT_ALLOWED');$p['base_distribution']=$p['distribution'];$p['discount']=$d;$p['distribution']-=$d;$p['discount_rate']=$rate;return $p;}
 private function token(int $net,array $p,int $expires):string{return $expires.'.'.hash_hmac('sha256',json_encode([$net,$this->auth->id(),$p,$expires]),DB_PASS);}
 public function quote(array $input):array{$net=$this->net($input);$name=$input['profile_name']??'';if(!is_string($name)||mb_strlen($name)>64)throw new InvalidArgumentException('INVALID_PROFILE');$p=$this->discount($this->profile($net,$name),$input);$expires=time()+300;return ['success'=>true,'distribution_price'=>$this->money($p['distribution']),'retail_price'=>$this->money($p['retail']),'quote_token'=>$this->token($net,$p,$expires),'expires_at'=>$expires];}
 public function fund(array $input):array{
  $net=$this->net($input);if(($input['cash_received']??false)!==true)throw new InvalidArgumentException('CASH_RECEIPT_REQUIRED');if(!in_array($this->auth->role(),['system_owner','superadmin','network_manager','admin','accountant','finance'],true))throw new DomainException('FORBIDDEN');$pos=$this->id($input['admin_id']??0);$this->auth->assertCanAccessAdmin($pos);$amount=$this->cents($input['amount']??'');if($amount<=0)throw new InvalidArgumentException('INVALID_AMOUNT');$cash=$this->id($input['cashbox_account_id']??0);$key=$this->key($input);$hash=hash('sha256',json_encode([$pos,$amount,$cash]));$this->db->beginTransaction();
  try{$q=$this->db->prepare('SELECT a.id FROM um_admins a JOIN um_admin_network_access n ON n.admin_id=a.id AND n.network_id=? AND n.is_active=1 AND (n.starts_at IS NULL OR n.starts_at<=NOW()) AND (n.expires_at IS NULL OR n.expires_at>NOW()) WHERE a.id=? AND a.is_active=1 FOR UPDATE');$q->execute([$net,$pos]);if(!$q->fetchColumn())throw new DomainException('FORBIDDEN_SCOPE');$q=$this->db->prepare('SELECT request_hash,journal_entry_id FROM um_wallet_funding WHERE network_id=? AND created_by=? AND request_key=? FOR UPDATE');$q->execute([$net,$this->auth->id(),$key]);if($old=$q->fetch(PDO::FETCH_ASSOC)){if(!hash_equals($old['request_hash'],$hash))throw new DomainException('IDEMPOTENCY_CONFLICT');$this->db->commit();return ['success'=>true,'replayed'=>true,'journal_entry_id'=>$old['journal_entry_id']];}
   $q=$this->db->prepare("SELECT id,owner_admin_id FROM um_chart_of_accounts WHERE network_id=? AND id=? AND account_type='asset' AND is_active=1 AND account_code LIKE '1101%' AND account_code<>'1101' FOR UPDATE");$q->execute([$net,$cash]);$acc=$q->fetch(PDO::FETCH_ASSOC);if(!$acc)throw new DomainException('CASHBOX_REQUIRED');if($acc['owner_admin_id'])$this->auth->assertCanAccessAdmin((int)$acc['owner_admin_id']);$advance=$this->account($net,'WALLET-ADV-'.$pos,'liability','دفعات محفظة نقطة البيع '.$pos);$ref='WF-'.bin2hex(random_bytes(16));$journal=$this->journal($ref,[['account_id'=>$cash,'debit'=>$this->money($amount),'credit'=>0],['account_id'=>$advance,'debit'=>0,'credit'=>$this->money($amount)]]);
   $q=$this->db->prepare('INSERT INTO um_agent_wallets(network_id,admin_id,balance) VALUES(?,?,?) ON DUPLICATE KEY UPDATE balance=balance+VALUES(balance)');$q->execute([$net,$pos,$this->money($amount)]);$q=$this->db->prepare('SELECT balance FROM um_agent_wallets WHERE network_id=? AND admin_id=?');$q->execute([$net,$pos]);$balance=$q->fetchColumn();$this->db->prepare("INSERT INTO um_wallet_transactions(network_id,admin_id,transaction_type,amount,balance_after,reference_type,reference_id,created_by) VALUES(?,?,'credit',?,?,'wallet_funding',?,?)")->execute([$net,$pos,$this->money($amount),$balance,$ref,$this->auth->id()]);$this->db->prepare('INSERT INTO um_wallet_funding(network_id,pos_admin_id,amount,journal_entry_id,request_key,request_hash,created_by) VALUES(?,?,?,?,?,?,?)')->execute([$net,$pos,$this->money($amount),$journal,$key,$hash,$this->auth->id()]);$this->party($net,$pos,-$amount,$ref,'receipt_voucher',$amount);$this->db->prepare("INSERT INTO um_vouchers_financial(network_id,voucher_no,voucher_type,party_id,amount,payment_method,category,reference_id,created_by) VALUES(?,?,'receipt',?,?,'cash','تمويل محفظة',?,?)")->execute([$net,$ref,$pos,$this->money($amount),$ref,$this->auth->id()]);$this->posJournal($net,$pos,$ref,'funding',[['POS_PREPAID',$amount,0],['POS_CASH',0,$amount]]);$this->db->commit();return ['success'=>true,'wallet_balance'=>$balance,'journal_entry_id'=>$journal];
  }catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw $e;}
 }
 public function sell(array $input):array{
  $net=$this->net($input);$pos=$this->auth->id();$key=$this->key($input);$name=$input['profile_name']??'';$phone=$input['phone']??'';$buyer=$input['buyer_name']??'';if(!is_string($name)||mb_strlen($name)>64||!is_string($phone)||!preg_match('/^[0-9]{9}$/',$phone)||!is_string($buyer)||mb_strlen($buyer)>128)throw new InvalidArgumentException('INVALID_SALE');if(($input['customer_cash_received']??false)!==true)throw new InvalidArgumentException('CUSTOMER_RECEIPT_REQUIRED');$hash=hash('sha256',json_encode([$name,$phone,trim($buyer),$this->cents($input['discount_amount']??'0')]));$this->db->beginTransaction();
  try{$q=$this->db->prepare('SELECT a.id FROM um_admins a JOIN um_admin_network_access n ON n.admin_id=a.id AND n.network_id=? AND n.is_active=1 AND (n.starts_at IS NULL OR n.starts_at<=NOW()) AND (n.expires_at IS NULL OR n.expires_at>NOW()) WHERE a.id=? AND a.is_active=1 FOR UPDATE');$q->execute([$net,$pos]);if(!$q->fetchColumn())throw new DomainException('FORBIDDEN_SCOPE');$q=$this->db->prepare('SELECT * FROM um_wallet_sales WHERE network_id=? AND pos_admin_id=? AND request_key=? FOR UPDATE');$q->execute([$net,$pos,$key]);if($old=$q->fetch(PDO::FETCH_ASSOC)){if(!hash_equals($old['request_hash'],$hash))throw new DomainException('IDEMPOTENCY_CONFLICT');if($old['status']!=='completed')throw new DomainException('SALE_ALREADY_REFUNDED');$this->db->commit();return ['success'=>true,'replayed'=>true,'voucher_id'=>$old['voucher_id'],'sale_id'=>$old['id'],'phone'=>$phone,'distribution_price'=>$old['distribution_amount'],'retail_price'=>$old['retail_amount']];}
   $p=$this->discount($this->profile($net,$name,true),$input);$token=$input['quote_token']??'';if(!is_string($token))throw new InvalidArgumentException('INVALID_QUOTE');$expires=(int)explode('.',$token,2)[0];if($expires<time()||$expires>time()+300||!hash_equals($this->token($net,$p,$expires),$token))throw new DomainException('QUOTE_CHANGED');$dist=$p['distribution'];$retail=$p['retail'];$q=$this->db->prepare('SELECT balance FROM um_agent_wallets WHERE network_id=? AND admin_id=? FOR UPDATE');$q->execute([$net,$pos]);$balance=$q->fetchColumn();if($balance===false||$this->cents($balance)<$dist)throw new DomainException('INSUFFICIENT_WALLET');
   $advance=$this->account($net,'WALLET-ADV-'.$pos,'liability','دفعات محفظة نقطة البيع '.$pos);$q=$this->db->prepare('SELECT balance FROM um_chart_of_accounts WHERE network_id=? AND id=?');$q->execute([$net,$advance]);$accountBalance=$q->fetchColumn();if($this->signed((string)$accountBalance)!==$this->cents($balance))throw new DomainException('WALLET_RECONCILIATION_REQUIRED');$revenue=$this->account($net,'WALLET-DIST-REV','revenue','مبيعات الكروت بسعر التوزيع');
   $q=$this->db->prepare('SELECT auth_mode,status FROM um_networks WHERE id=?');$q->execute([$net]);$network=$q->fetch(PDO::FETCH_ASSOC);if(!$network||$network['status']!=='active')throw new DomainException('FORBIDDEN_NETWORK');$code=(string)random_int(1000000000000000,9999999999999999);$q=$this->db->prepare('SELECT 1 FROM um_vouchers_meta WHERE network_id=? AND username=? LIMIT 1');$q->execute([$net,$code]);if($q->fetchColumn())throw new DomainException('CARD_CODE_COLLISION');foreach(['radcheck','radusergroup'] as $authTable){$q=$this->db->prepare('SELECT 1 FROM '.$authTable.' WHERE network_id=? AND username=? LIMIT 1');$q->execute([$net,$code]);if($q->fetchColumn())throw new DomainException('CARD_CODE_COLLISION');}$password=match($network['auth_mode']){'username_only'=>'','same'=>$code,'different'=>(string)random_int(1000000000000000,9999999999999999),default=>throw new DomainException('AUTH_MODE_INVALID')};if($network['auth_mode']==='different'&&$password===$code)throw new DomainException('CARD_CODE_COLLISION');
   $ref='WS-'.bin2hex(random_bytes(16));$q=$this->db->prepare("INSERT INTO um_vouchers_meta(network_id,username,batch_id,profile_name,price,validity,status,comment,owner_admin_id,sold_by_admin_id,sold_at,sale_price,purchase_cost,profit_amount,buyer_phone,buyer_name,is_sold,delivery_status,login_password_mode) VALUES(?,?,?,?,?,?,'active','بيع إلكتروني بالمحفظة',?,?,NOW(),?,?,?,?,?,1,'pending',?)");$q->execute([$net,$code,$ref,$name,$this->money($retail),$p['validity'],$pos,$pos,$this->money($dist),'0.00',$this->money($dist),$phone,trim($buyer),$network['auth_mode']==='username_only'?'blank':($network['auth_mode']==='same'?'same_as_username':'different')]);$voucher=(int)$this->db->lastInsertId();$this->db->prepare("INSERT INTO radcheck(network_id,username,attribute,op,value) VALUES(?,?,'Cleartext-Password',':=',?)")->execute([$net,$code,$password]);$this->db->prepare('INSERT INTO radusergroup(network_id,username,groupname,priority) VALUES(?,?,?,1)')->execute([$net,$code,$name]);
   $new=$this->money($this->cents($balance)-$dist);$this->db->prepare('UPDATE um_agent_wallets SET balance=? WHERE network_id=? AND admin_id=?')->execute([$new,$net,$pos]);$this->db->prepare("INSERT INTO um_wallet_transactions(network_id,admin_id,transaction_type,amount,balance_after,reference_type,reference_id,created_by) VALUES(?,?,'voucher_sale',?,?,'voucher',?,?)")->execute([$net,$pos,'-'.$this->money($dist),$new,$code,$pos]);$journal=$this->journal($ref,[['account_id'=>$advance,'debit'=>$this->money($dist),'credit'=>0],['account_id'=>$revenue,'debit'=>0,'credit'=>$this->money($dist)]]);$posJournal=$this->posJournal($net,$pos,$ref,'retail_sale',[['POS_CASH',$retail,0],['POS_RETAIL_REVENUE',0,$retail],['POS_COST',$dist,0],['POS_PREPAID',0,$dist]]);
   $this->db->prepare('INSERT INTO um_wallet_sales(network_id,pos_admin_id,voucher_id,invoice_no,distribution_amount,retail_amount,network_journal_id,pos_journal_id,request_key,request_hash,created_by) VALUES(?,?,?,?,?,?,?,?,?,?,?)')->execute([$net,$pos,$voucher,$ref,$this->money($dist),$this->money($retail),$journal,$posJournal,$key,$hash,$pos]);$sale=(int)$this->db->lastInsertId();$q=$this->db->prepare('SELECT created_by FROM um_networks WHERE id=?');$q->execute([$net]);$seller=(int)$q->fetchColumn();$q=$this->db->prepare("INSERT INTO um_sales_invoices(network_id,invoice_no,sale_kind,seller_id,buyer_id,profile_name,quantity,unit_price,total_amount,cost_amount,profit_amount,paid_amount,remaining_amount,payment_type,notes) VALUES(?,?,'wallet_distribution',?,?,?,1,?,?,0,?,?,0,'wallet','بيع الشبكة بسعر التوزيع؛ قبض العميل في دفاتر نقطة البيع المنفصلة')");$q->execute([$net,$ref,$seller,$pos,$name,$this->money($dist),$this->money($dist),$this->money($dist),$this->money($dist)]);$invoice=(int)$this->db->lastInsertId();$this->db->prepare("INSERT INTO um_sales_invoice_items(network_id,invoice_id,item_type,profile_name,batch_id,sheets_count,cards_count,unit_price,gross_amount,discount_amount,net_amount,cost_amount,profit_amount) VALUES(?,?,'wallet_distribution',?,?,0,1,?,?,?,?,0,?)")->execute([$net,$invoice,$name,$ref,$this->money($p['base_distribution']),$this->money($p['base_distribution']),$this->money($p['discount']),$this->money($dist),$this->money($dist)]);$this->db->prepare('UPDATE um_wallet_sales SET network_invoice_id=? WHERE id=?')->execute([$invoice,$sale]);$this->db->prepare('UPDATE um_vouchers_meta SET invoice_id=? WHERE id=? AND network_id=?')->execute([$invoice,$voucher,$net]);$this->party($net,$pos,$dist,$ref,'sale_invoice',0);$this->db->commit();return ['success'=>true,'sale_id'=>$sale,'voucher_id'=>$voucher,'phone'=>$phone,'distribution_price'=>$this->money($dist),'retail_price'=>$this->money($retail),'wallet_balance'=>$new,'delivery_status'=>'pending','message'=>'سُجل بيع الشبكة وقبض العميل في دفاتر منفصلة؛ لم يُؤكد التسليم بعد'];
  }catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw $e;}
 }
 public function reverse(int $voucher,int $amount):void{
  $net=$this->auth->activeNetworkId();$q=$this->db->prepare('SELECT * FROM um_wallet_sales WHERE network_id=? AND voucher_id=? FOR UPDATE');$q->execute([$net,$voucher]);$sale=$q->fetch(PDO::FETCH_ASSOC);if(!$sale)return;if($sale['status']!=='completed'||$this->cents($sale['distribution_amount'])!==$amount)throw new DomainException('REFUND_INCOMPLETE');$q=$this->db->prepare("SELECT 1 FROM um_journal_entries j JOIN um_sales_invoices i ON i.id=? AND i.network_id=j.network_id WHERE j.network_id=? AND j.id=? AND j.is_posted=1 AND j.source_module='wallet_distribution' AND j.reference_no=? AND j.total_debit=? AND j.total_credit=? AND i.sale_kind='wallet_distribution' AND i.invoice_status='completed' AND i.total_amount=? AND i.buyer_id=?");$q->execute([$sale['network_invoice_id'],$net,$sale['network_journal_id'],$sale['invoice_no'],$this->money($amount),$this->money($amount),$this->money($amount),$sale['pos_admin_id']]);if(!$q->fetchColumn())throw new DomainException('REFUND_INCOMPLETE');$pos=(int)$sale['pos_admin_id'];$advance=$this->account($net,'WALLET-ADV-'.$pos,'liability','دفعات محفظة نقطة البيع '.$pos);$revenue=$this->account($net,'WALLET-DIST-REV','revenue','مبيعات الكروت بسعر التوزيع');$ref='WR-'.$sale['invoice_no'];$journal=$this->journal($ref,[['account_id'=>$revenue,'debit'=>$this->money($amount),'credit'=>0],['account_id'=>$advance,'debit'=>0,'credit'=>$this->money($amount)]]);$retail=$this->cents($sale['retail_amount']);$this->posJournal($net,$pos,$ref,'refund_due',[['POS_RETAIL_REVENUE',$retail,0],['POS_CUSTOMER_REFUND_DUE',0,$retail],['POS_PREPAID',$amount,0],['POS_COST',0,$amount]]);$this->db->prepare("UPDATE um_sales_invoices SET invoice_status='refunded',refunded_at=NOW() WHERE network_id=? AND id=? AND sale_kind='wallet_distribution'")->execute([$net,$sale['network_invoice_id']]);$this->party($net,$pos,-$amount,$ref,'adjustment',0);$this->db->prepare("UPDATE um_wallet_sales SET status='refunded',refund_journal_id=?,customer_refund_due=? WHERE id=? AND network_id=?")->execute([$journal,$this->money($retail),$sale['id'],$net]);
 }
 public function records(array $input,bool $posBook):array{$net=$this->net($input);$pos=$this->id($input['admin_id']??$this->auth->id());$this->auth->assertCanAccessAdmin($pos);$limit=max(1,min(500,(int)($input['limit']??100)));$before=max(0,(int)($input['before_id']??0));$table=$posBook?'um_pos_journals':'um_wallet_sales';$q=$this->db->prepare('SELECT * FROM '.$table.' WHERE network_id=? AND pos_admin_id=?'.($before?' AND id<?':'').' ORDER BY id DESC LIMIT '.($limit+1));$q->execute($before?[$net,$pos,$before]:[$net,$pos]);$rows=$q->fetchAll(PDO::FETCH_ASSOC);$more=count($rows)>$limit;if($more)array_pop($rows);foreach($rows as &$r)unset($r['request_hash'],$r['request_key']);unset($r);if($posBook&&$rows){$ids=array_column($rows,'id');$q=$this->db->prepare('SELECT journal_id,account_code,debit,credit FROM um_pos_journal_lines WHERE network_id=? AND pos_admin_id=? AND journal_id IN ('.implode(',',array_fill(0,count($ids),'?')).') ORDER BY id');$q->execute([$net,$pos,...$ids]);$lines=[];foreach($q->fetchAll(PDO::FETCH_ASSOC) as $line)$lines[$line['journal_id']][]=$line;foreach($rows as &$r)$r['lines']=$lines[$r['id']]??[];unset($r);}return ['success'=>true,'book'=>$posBook?'pos_only':'network_distribution','data'=>$rows,'has_more'=>$more,'next_cursor'=>$rows?(int)end($rows)['id']:null];}
}
